-- Módulos do hub INOVATEC: oficinas, lista CSV e programação.
create table if not exists public.inovatec_oficinas (id bigint generated by default as identity primary key,titulo text not null,descricao text,data_hora timestamptz,local text,vagas integer not null check(vagas>0),ativa boolean not null default true,criado_em timestamptz not null default now());
create table if not exists public.inovatec_estudantes (id bigint generated by default as identity primary key,nome_completo text not null,nome_normalizado text not null unique,email text not null,telefone text,ativo boolean not null default true);
create table if not exists public.inovatec_oficina_inscricoes (id bigint generated by default as identity primary key,estudante_id bigint not null references public.inovatec_estudantes(id),oficina_id bigint not null references public.inovatec_oficinas(id) on delete cascade,criado_em timestamptz not null default now(),unique(estudante_id,oficina_id));
create table if not exists public.inovatec_programacao (id bigint generated by default as identity primary key,nome text not null,data_hora timestamptz not null,local text not null,ativo boolean not null default true);
create or replace function public.normalizar_nome_inovatec(v text) returns text language sql immutable as $$select lower(trim(regexp_replace(translate(coalesce(v,''),'ÁÀÃÂÄÉÊÈËÍÌÎÏÓÒÔÕÖÚÙÛÜÇÑáàãâäéêèëíìîïóòôõöúùûüçñ','AAAAAEEEEIIIIOOOOOUUUUCNaaaaaeeeeiiiiOOOOOuuuucc'),'\s+',' ','g')))$$;
alter table public.inovatec_oficinas enable row level security; alter table public.inovatec_estudantes enable row level security; alter table public.inovatec_oficina_inscricoes enable row level security; alter table public.inovatec_programacao enable row level security;
create policy "coord oficinas" on public.inovatec_oficinas for all to authenticated using(public.usuario_e_coordenador()) with check(public.usuario_e_coordenador());
create policy "coord estudantes inovatec" on public.inovatec_estudantes for all to authenticated using(public.usuario_e_coordenador()) with check(public.usuario_e_coordenador());
create policy "coord inscricoes oficinas" on public.inovatec_oficina_inscricoes for all to authenticated using(public.usuario_e_coordenador()) with check(public.usuario_e_coordenador());
create policy "coord programacao inovatec" on public.inovatec_programacao for all to authenticated using(public.usuario_e_coordenador()) with check(public.usuario_e_coordenador());
create or replace function public.listar_programacao_inovatec() returns table(id bigint,nome text,data_hora timestamptz,local text) language sql security definer as $$select id,nome,data_hora,local from public.inovatec_programacao where ativo order by data_hora$$;
grant execute on function public.listar_programacao_inovatec() to anon,authenticated;
create or replace function public.listar_oficinas_inovatec() returns table(id bigint,titulo text,descricao text,data_hora timestamptz,local text,vagas integer,vagas_disponiveis bigint) language sql security definer as $$select o.id,o.titulo,o.descricao,o.data_hora,o.local,o.vagas,greatest(o.vagas-count(i.id),0)::bigint from public.inovatec_oficinas o left join public.inovatec_oficina_inscricoes i on i.oficina_id=o.id where o.ativa group by o.id order by o.data_hora nulls last,o.titulo$$;
create or replace function public.buscar_estudante_inovatec(p_nome text,p_email text) returns table(nome_completo text) language sql security definer as $$select nome_completo from public.inovatec_estudantes where ativo and nome_normalizado=public.normalizar_nome_inovatec(p_nome) and lower(email)=lower(trim(p_email)) limit 1$$;
create or replace function public.inscrever_inovatec(p_nome text,p_email text,p_oficina_id bigint) returns boolean language plpgsql security definer as $$declare e public.inovatec_estudantes%rowtype;o public.inovatec_oficinas%rowtype;n integer;begin select * into e from public.inovatec_estudantes where ativo and nome_normalizado=public.normalizar_nome_inovatec(p_nome) and lower(email)=lower(trim(p_email)) limit 1;if not found then raise exception 'Nome completo e e-mail não constam na lista de estudantes habilitados.';end if;select * into o from public.inovatec_oficinas where id=p_oficina_id and ativa for update;if not found then raise exception 'Oficina indisponível.';end if;if exists(select 1 from public.inovatec_oficina_inscricoes where estudante_id=e.id and oficina_id=o.id) then raise exception 'Você já está inscrito nesta oficina.';end if;select count(*) into n from public.inovatec_oficina_inscricoes where oficina_id=o.id;if n>=o.vagas then raise exception 'As vagas desta oficina foram preenchidas.';end if;insert into public.inovatec_oficina_inscricoes(estudante_id,oficina_id) values(e.id,o.id);return true;end$$;
grant execute on function public.listar_oficinas_inovatec() to anon,authenticated; grant execute on function public.buscar_estudante_inovatec(text,text) to anon,authenticated; grant execute on function public.inscrever_inovatec(text,text,bigint) to anon,authenticated;
